create extension if not exists "uuid-ossp";
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text, account_type text check(account_type in ('individual','family','teacher','academy')), created_at timestamptz default now());
create table if not exists organizations(id uuid primary key default uuid_generate_v4(), name text not null, created_at timestamptz default now());
create table if not exists students(id uuid primary key default uuid_generate_v4(), profile_id uuid references profiles(id), organization_id uuid references organizations(id), name text not null, age int, preferred_language text default 'Urdu', learning_mode text check(learning_mode in ('Nazirah','Hifz','Both')), current_surah int, current_ayah int, current_page int, current_juz int, created_at timestamptz default now());
create table if not exists quran_ayahs(id bigint primary key, verse_key text unique not null, surah int not null, ayah int not null, page int, juz int, canonical_text text not null, checksum text);
create table if not exists quran_words(id text primary key, verse_key text references quran_ayahs(verse_key), position int not null, canonical_text text not null, page int, line int, audio_reference text);
create table if not exists student_quran_progress(id uuid primary key default uuid_generate_v4(), student_id uuid references students(id) on delete cascade, current_sabaq jsonb, current_sabqi jsonb, current_manzil jsonb, nazirah_position jsonb, memorized_ayahs jsonb default '[]', weak_ayah_score jsonb default '{}', weak_word_score jsonb default '{}', updated_at timestamptz default now());
create table if not exists lesson_sessions(id uuid primary key default uuid_generate_v4(), student_id uuid references students(id) on delete cascade, started_at timestamptz, ended_at timestamptz, lesson_plan jsonb, summary jsonb, created_at timestamptz default now());
create table if not exists recitation_attempts(id uuid primary key default uuid_generate_v4(), student_id uuid references students(id), session_id uuid references lesson_sessions(id), verse_key text, start_word text, end_word text, audio_storage_reference text, expected_word_ids jsonb not null default '[]', recognized_sequence jsonb, accuracy_score numeric, fluency_score numeric, mistake_count int default 0, recognition_confidence numeric, duration_ms int, created_at timestamptz default now());
create table if not exists mistakes(id uuid primary key default uuid_generate_v4(), student_id uuid references students(id), session_id uuid references lesson_sessions(id), recitation_attempt_id uuid references recitation_attempts(id), verse_key text, word_id text, mistake_type text, expected_value text, recognized_value text, confidence numeric, corrected boolean default false, number_of_retries int default 0, created_at timestamptz default now());
create table if not exists revision_schedule(id uuid primary key default uuid_generate_v4(), student_id uuid references students(id), verse_key text not null, memory_strength numeric default .5, due_at timestamptz, interval_days int default 1, last_result jsonb, updated_at timestamptz default now());
create table if not exists class_schedule(id uuid primary key default uuid_generate_v4(), student_id uuid references students(id), timezone text default 'Asia/Karachi', class_time time, class_days int[] default '{1,2,3,4,5,6}', enabled boolean default true);
create table if not exists teacher_notes(id uuid primary key default uuid_generate_v4(), student_id uuid references students(id), teacher_id uuid references profiles(id), note text not null, created_at timestamptz default now());
create table if not exists plans(id uuid primary key default uuid_generate_v4(), code text unique not null, name text not null, limits jsonb default '{}');
create table if not exists subscriptions(id uuid primary key default uuid_generate_v4(), profile_id uuid references profiles(id), organization_id uuid references organizations(id), plan_id uuid references plans(id), status text, starts_at timestamptz, ends_at timestamptz);
create table if not exists audit_logs(id bigint generated always as identity primary key, actor_id uuid, entity_type text, entity_id text, action text, before_data jsonb, after_data jsonb, created_at timestamptz default now());